from AlgorithmImports import *
from datetime import datetime, time, timedelta


class SPYOptionCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone("America/New_York")

        # Equity Subscription: SPY minute resolution, raw prices
        self.spy = self.add_equity(
            "SPY", Resolution.MINUTE, data_normalization_mode=DataNormalizationMode.RAW
        )
        self.spy_symbol = self.spy.symbol

        # Option Subscription: SPY options at minute resolution
        self.option = self.add_option("SPY", Resolution.MINUTE)
        self.option_symbol = self.option.symbol
        self.option.set_filter(
            lambda u: u.calls_only().expiration(7, 60).strikes(0, 40)
        )

        # Consolidator for 5-minute bars
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.data_consolidated += self.on_five_minute_bar
        self.subscription_manager.add_consolidator(
            self.spy_symbol, self.consolidator
        )

        # Moving Averages (5-bar and 20-bar SMAs of 5-minute closes)
        self.fast_ma = SimpleMovingAverage(5)
        self.slow_ma = SimpleMovingAverage(20)

        # State Tracking
        self.prev_fast = None
        self.prev_slow = None
        self.pending_entry_signal = False

        self.held_contract = None
        self.entry_price = None
        self.entry_order_ticket = None
        self.no_entry_date = None

    def on_five_minute_bar(self, sender, bar):
        # Update indicators with the 5-minute closing price
        self.fast_ma.update(bar.end_time, bar.close)
        self.slow_ma.update(bar.end_time, bar.close)

        # Ensure both moving averages are ready
        if self.fast_ma.is_ready and self.slow_ma.is_ready:
            if self.prev_fast is not None and self.prev_slow is not None:
                curr_fast = self.fast_ma.current.value
                curr_slow = self.slow_ma.current.value

                # Bullish crossover condition: Fast <= Slow on prev bar and Fast > Slow on current bar
                is_crossover = (self.prev_fast <= self.prev_slow) and (
                    curr_fast > curr_slow
                )

                if is_crossover:
                    # Check window: Crossover bar ends from 09:45 through 14:30 NY time inclusive
                    bar_end_time = bar.end_time.time()
                    if time(9, 45) <= bar_end_time <= time(14, 30):
                        self.pending_entry_signal = True
                        self.debug(
                            f"Bullish crossover detected at {bar.end_time}. Fast: {curr_fast:.2f}, Slow: {curr_slow:.2f}"
                        )

            self.prev_fast = self.fast_ma.current.value
            self.prev_slow = self.slow_ma.current.value

    def on_data(self, slice):
        if self.is_warming_up:
            return

        # Process pending entry signal immediately on bar close slice
        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.try_execute_entry(slice)

        # Evaluate exit logic for held option positions
        self.evaluate_exits(slice)

    def try_execute_entry(self, slice):
        # Do not open replacement if blocked for today
        if self.no_entry_date == self.time.date():
            self.debug(
                f"Entry skipped at {self.time}: Trading blocked for today."
            )
            return

        # Check existing holdings or pending entry orders
        has_option_holding = any(
            sec.value.invested
            for sec in self.portfolio
            if sec.key.security_type == SecurityType.OPTION
        )
        has_pending_entry = (
            self.entry_order_ticket is not None
            and self.entry_order_ticket.status
            in [
                OrderStatus.SUBMITTED,
                OrderStatus.NEW,
                OrderStatus.PARTIALLY_FILLED,
            ]
        )

        if has_option_holding or has_pending_entry:
            self.debug(
                f"Entry skipped at {self.time}: Position or entry order already active."
            )
            return

        # Select option contract
        contract_symbol = self.select_contract(slice)
        if contract_symbol is None:
            return

        # Execute entry market order for 1 contract
        self.held_contract = contract_symbol
        self.entry_order_ticket = self.market_order(contract_symbol, 1)
        self.debug(
            f"Submitted market buy order for contract {contract_symbol.value} at {self.time}"
        )

    def select_contract(self, slice):
        # Retrieve option chain from slice
        chain = slice.option_chains.get(self.option_symbol)
        if not chain:
            self.debug(
                f"Entry signal skipped at {self.time}: Option chain missing in current slice."
            )
            return None

        # Get current underlying price
        if slice.bars.contains_key(self.spy_symbol):
            spy_price = slice.bars[self.spy_symbol].close
        else:
            spy_price = self.securities[self.spy_symbol].price

        if spy_price <= 0:
            self.debug(
                f"Entry signal skipped at {self.time}: Invalid SPY price ({spy_price})."
            )
            return None

        current_date = self.time.date()

        # Filter target expiration: nearest expiration >= 7 calendar days after current date
        valid_expirations = set()
        for contract in chain:
            if contract.right == OptionRight.CALL:
                dte = (contract.expiry.date() - current_date).days
                if dte >= 7:
                    valid_expirations.add(contract.expiry.date())

        if not valid_expirations:
            self.debug(
                f"Entry signal skipped at {self.time}: No expiration with DTE >= 7 calendar days."
            )
            return None

        target_expiration = min(valid_expirations)
        target_strike_min = 1.01 * spy_price

        # Filter calls for selected expiration with strike >= 101% of SPY price
        candidate_contracts = []
        for contract in chain:
            if (
                contract.right == OptionRight.CALL
                and contract.expiry.date() == target_expiration
            ):
                if contract.strike >= target_strike_min:
                    candidate_contracts.append(contract)

        if not candidate_contracts:
            self.debug(
                f"Entry signal skipped at {self.time}: No call contract with strike >= 101% of SPY ({target_strike_min:.2f}) for exp {target_expiration}."
            )
            return None

        # Sort by strike ascending, tie-break by ascending string value of contract Symbol
        candidate_contracts.sort(key=lambda c: (c.strike, str(c.symbol)))
        selected_contract = candidate_contracts[0]

        return selected_contract.symbol

    def evaluate_exits(self, slice):
        if (
            self.held_contract is None
            or not self.portfolio[self.held_contract].invested
        ):
            return

        # Avoid submitting multiple exit market orders if one is already open
        if self.transactions.get_open_orders(self.held_contract):
            return

        expiry_date = self.held_contract.id.date

        # Scheduled Time Stop: 15:45 NY time on trading day immediately preceding expiration date
        if self.time.hour == 15 and self.time.minute == 45:
            if self.is_pre_expiration_trading_day(expiry_date):
                self.debug(
                    f"Scheduled time stop exit triggered at 15:45 for {self.held_contract.value}"
                )
                self.liquidate(self.held_contract)
                return

        # Expiration Safety Stop: Never hold into expiration
        if self.time.date() >= expiry_date:
            self.debug(
                f"Expiration safety liquidation triggered for {self.held_contract.value} on {self.time.date()}"
            )
            self.liquidate(self.held_contract)
            self.no_entry_date = self.time.date()
            return

        # Profit Target Exit: Midpoint >= 1.50 * entry price
        if slice.quote_bars.contains_key(self.held_contract):
            qb = slice.quote_bars[self.held_contract]
            if qb.bid is not None and qb.ask is not None:
                bid = qb.bid.close
                ask = qb.ask.close
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if (
                        self.entry_price is not None
                        and midpoint >= 1.50 * self.entry_price
                    ):
                        self.debug(
                            f"Profit target hit for {self.held_contract.value}: Midpoint={midpoint:.2f}, Entry={self.entry_price:.2f}"
                        )
                        self.liquidate(self.held_contract)

    def is_pre_expiration_trading_day(self, expiry_date):
        # Search trading days in the week prior to expiry date
        start_search = expiry_date - timedelta(days=7)
        end_search = expiry_date - timedelta(days=1)
        trading_days = [
            day.date.date()
            for day in self.trading_calendar.get_trading_days(
                start_search, end_search
            )
            if day.is_open
        ]
        if trading_days:
            return self.time.date() == trading_days[-1]
        return False

    def on_order_event(self, order_event):
        if order_event.status == OrderStatus.FILLED:
            if order_event.direction == OrderDirection.BUY:
                if (
                    self.entry_order_ticket is not None
                    and order_event.order_id
                    == self.entry_order_ticket.order_id
                ):
                    self.entry_price = order_event.fill_price
                    self.debug(
                        f"Entry order filled for {order_event.symbol.value} at recorded fill price {self.entry_price:.2f}"
                    )
            elif order_event.direction == OrderDirection.SELL:
                self.debug(
                    f"Exit order filled for {order_event.symbol.value} at price {order_event.fill_price:.2f}"
                )
                if (
                    self.held_contract is not None
                    and order_event.symbol == self.held_contract
                ):
                    self.held_contract = None
                    self.entry_price = None
                    self.entry_order_ticket = None

    def on_assignment_event(self, assignment_event):
        self.debug(
            f"Unexpected assignment event for {assignment_event.symbol.value}: {assignment_event}"
        )
        self.no_entry_date = self.time.date()
        self.liquidate(self.spy_symbol)
